    public static function handle(string $action): void {ZP_Content_Preparation_20261010::guard($action);$code='research_saved';$plan=null;try{self::allowed();if($action==='zp_prep_statistics_adopt')self::adopt();elseif($action==='zp_prep_statistics_articles'){if(self::scalar('statistics_cost_ack')!=='1')throw new RuntimeException('retry_confirmation');$count=self::scalar('statistics_count','1');if(!ctype_digit($count))throw new RuntimeException('invalid_input');$plan=ZP_Content_Preparation_20261010::gap_plan(self::scalar('statistics_start'),self::scalar('statistics_end'),self::scalar('statistics_clock','18:00'));if(!hash_equals($plan['digest'],self::scalar('statistics_digest')))throw new RuntimeException('gap_changed');self::start_articles((int)$count,self::scalar('statistics_market','national'),$plan);$code='auto_started';}else throw new RuntimeException('invalid_input');}catch(Throwable$e){$safe=['actor_permissions','research_changed','research_stale','storage_failed','busy','insufficient_topics','invalid_input','retry_confirmation','verify_models','service_catalog','invalid_template','invalid_template_css','invalid_gap_range','invalid_date','gap_changed','gap_capacity','history_limit','cron_failed'];$code=$e instanceof RuntimeException&&in_array($e->getMessage(),$safe,true)?$e->getMessage():'unexpected';}wp_safe_redirect(ZP_Content_Preparation_20261010::gap_redirect_url($code,$plan));exit;}
    private static function form(string $action): void {echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'"><input type="hidden" name="action" value="'.esc_attr($action).'">';wp_nonce_field($action);if(function_exists('zp_suite_workspace_active')&&zp_suite_workspace_active())echo '<input type="hidden" name="_zp_workspace" value="1">';}
    public static function render(?array $plan): void {if(!ZP_Content_Preparation_20261010::allowed()||!current_user_can('unfiltered_html'))return;try{$m=self::manifest();$pool=self::pool($m);$s=self::state();$ready=(bool)$s;$rows=$ready?self::rows('national'):$pool;}catch(Throwable$e){echo '<section class="zpAdmin20__card"><h2>Nowe tematy stron i sklepów</h2><p>Zapisane pomiary wymagają sprawdzenia. Nie uruchamiamy nowych zapytań Senuto.</p></section>';return;}
        echo '<section class="zpAdmin20__card"><h2>Nowe tematy stron i sklepów</h2><p>16 odrębnych problemów z dwóch potwierdzonych raportów Senuto: krajowy wolumen PL1 co najmniej 150. Pomiary pobrano 11.10.2026; Senuto nie podało w eksporcie daty okresu pomiaru. Wybór uwzględnia obecne wpisy, szkice i rezerwacje. To propozycje redakcyjne, nie prognoza liczby klientów.</p><p><b>'.esc_html($ready?'Dostępne rodziny:':'Rodziny w potwierdzonej puli:').' '.count($rows).' / 16.</b> Synonimy nie stają się dodatkowymi artykułami. Katowice oznacza odbiorcę i właściwą usługę, a wolumen pozostaje krajowy.</p>';
        if(!$ready){echo '<p>Przyjęcie tych zapisanych wyników jest bezpłatne: nie wysyła nowego żądania Senuto i nie zużywa kolejnej jednostki limitu.</p>';self::form('zp_prep_statistics_adopt');echo '<button class="button">Użyj potwierdzonych pomiarów</button></form>';}elseif($plan&&count($rows)){self::form('zp_prep_statistics_articles');foreach(['statistics_start'=>$plan['start'],'statistics_end'=>$plan['end'],'statistics_clock'=>$plan['clock'],'statistics_digest'=>$plan['digest']]as$k=>$v)echo '<input type="hidden" name="'.esc_attr($k).'" value="'.esc_attr($v).'">';echo '<div class="zpAdmin20__formGrid"><label class="zpAdmin20__field">Liczba artykułów<select name="statistics_count">';foreach([1,2,3,4,5,10]as$n)if($n<=count($rows)&&$n<=count($plan['dates']))echo '<option value="'.$n.'">'.$n.'</option>';echo '</select></label><label class="zpAdmin20__field">Odbiorca<select name="statistics_market"><option value="national">Polska</option><option value="katowice">Katowice</option></select></label></div><label style="display:block"><input type="checkbox" name="statistics_cost_ack" value="1" required> Uruchamiam dobór i przygotowanie wybranej partii. Tekst i trzy obrazy (okładka i dwie odrębne ilustracje) korzystają z płatnego API OpenAI.</label><p>Obecny generator obsługuje do 10 artykułów jednocześnie. Pulę 16 można uzupełnić partiami 10, 5 i 1; po każdej partii sprawdzamy aktualne wolne terminy i wykorzystane rodziny. Generację blokuje aktywna kolejka lub stan wymagający sprawdzenia.</p><button class="button button-primary">Dobierz i przygotuj artykuły</button></form>';}
        echo '<details><summary>Tematy, zakres i potwierdzone wolumeny</summary><div class="zpAdmin20__tableWrap"><table class="zpAdmin20__table"><thead><tr><th>Dokładna fraza</th><th>Wolumen PL1</th><th>Odrębny problem</th></tr></thead><tbody>';foreach($rows as$r){$f=$m['families'][$r['statistics_family']];echo '<tr><td>'.esc_html($r['keyword']).'</td><td>'.(int)$r['volume'].'</td><td>'.esc_html($f['angle']).'<br><small>'.esc_html($f['distinctness_reason']).'</small></td></tr>';}echo '</tbody></table></div></details></section>';
    }
